const $=id=>document.getElementById(id),home=$('home'),roomEl=$('room'),errorEl=$('error'),clock=$('clock'),display=$('display'),stageLabel=$('stage-label'),stageTitle=$('stage-title'),stageCopy=$('stage-copy'),tap=$('tap'),startBtn=$('start-round'),newBtn=$('new-round');let session=null,state=null,offset=0,pollTimer,frame;
const request=async(path,options={})=>{const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw new Error(data.error||'Something went wrong.');return data};const post=(path,body)=>request(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const roomLink=code=>`${location.origin}/ten-seconds/?room=${code}`;
function save(){sessionStorage.setItem('ten00.session',JSON.stringify(session))}function load(){try{return JSON.parse(sessionStorage.getItem('ten00.session'))}catch{return null}}function showError(message=''){errorEl.textContent=message}
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===button));$('create-form').hidden=button.dataset.tab!=='create';$('join-form').hidden=button.dataset.tab!=='join'});
$('create-form').onsubmit=async e=>{e.preventDefault();showError();try{const data=await post('/api/timer/rooms',{name:$('create-name').value,penalty:$('penalty').value});session={code:data.code,playerToken:data.playerToken,hostToken:data.hostToken};save();enter(data.state)}catch(error){showError(error.message)}};
$('join-form').onsubmit=async e=>{e.preventDefault();showError();try{const data=await post('/api/timer/join',{code:$('join-code').value,name:$('join-name').value});session={code:data.code,playerToken:data.playerToken};save();enter(data.state)}catch(error){showError(error.message)}};
function enter(next){state=next;offset=next.serverNow-Date.now();home.hidden=true;roomEl.hidden=false;$('copy-code').textContent=session.code;render();clearInterval(pollTimer);pollTimer=setInterval(poll,700)}async function poll(){if(!session)return;try{const next=await request(`/api/timer/room?code=${encodeURIComponent(session.code)}&token=${encodeURIComponent(session.playerToken)}`);state=next;offset=next.serverNow-Date.now();render()}catch(error){showError(error.message)}}
function renderPlayers(){const revealed=state.room.status==='results',ranked=state.players.filter(p=>p.tapMs!==undefined).sort((a,b)=>a.rank-b.rank),loser=ranked.at(-1)?.id;$('player-count').textContent=`${state.players.length} / 8`;$('player-list').innerHTML=state.players.map(p=>`<div class="player ${p.hasTapped?'ready':''} ${p.rank===1?'winner':''} ${p.id===loser&&ranked.length>1?'loser':''}"><span><i></i>${escapeHtml(p.name)}${p.id===state.me?.id?' · YOU':''}</span><b>${revealed?(p.tapMs===undefined?'NO TAP':`${(p.tapMs/1000).toFixed(2)}s${p.rank===1?' · WINNER':''}`):(p.hasTapped?'LOCKED':'')}</b></div>`).join('')}
function render(){if(!state)return;const r=state.room,isHost=!!session.hostToken;renderPlayers();startBtn.hidden=!(isHost&&r.status==='lobby');newBtn.hidden=true;tap.hidden=true;clock.className='clock';if(r.status==='lobby'){display.textContent='10:00';$('clock-label').textContent='TARGET TIME';$('subdisplay').textContent='WAITING TO START';stageLabel.textContent='WAITING ROOM';stageTitle.textContent=isHost?'Everyone ready?':'Waiting for the host.';stageCopy.textContent=`Loser: ${r.penalty}`;startBtn.textContent='START 3 · 2 · 1'}else if(r.status==='countdown'||r.status==='playing'){startBtn.hidden=true;runClock()}else{cancelAnimationFrame(frame);clock.classList.add('results');const ranked=state.players.filter(p=>p.rank).sort((a,b)=>a.rank-b.rank),winner=ranked[0],loser=ranked.at(-1),me=state.players.find(p=>p.id===state.me?.id),shown=me?.tapMs!==undefined?me:winner;display.textContent=shown?`${(shown.tapMs/1000).toFixed(2)}`:'--:--';$('clock-label').textContent=me?.tapMs!==undefined?'YOUR TIME':winner?`${winner.name.toUpperCase()} WINS`:'ROUND OVER';$('subdisplay').textContent=winner?`${winner.name.toUpperCase()} WAS CLOSEST TO 10.00`:'NO TIMES RECORDED';stageLabel.textContent=`ROUND ${r.round} RESULTS`;stageTitle.textContent=winner?`${winner.name} wins!`:'No taps this round.';stageCopy.textContent=loser&&ranked.length>1?`${loser.name} is furthest — ${r.penalty}`:'Times are shown below.';newBtn.hidden=!isHost}}
function runClock(){cancelAnimationFrame(frame);const tick=()=>{const until=state.room.startAt-(Date.now()+offset);if(until>0){clock.className='clock countdown';display.textContent=String(Math.min(3,Math.ceil(until/1000)));$('clock-label').textContent='GET READY';$('subdisplay').textContent='THE CLOCK HIDES AT GO';stageLabel.textContent='EVERYONE STARTS TOGETHER';stageTitle.textContent='Hands off!';stageCopy.textContent='Wait for GO.';tap.hidden=true}else{clock.className='clock blind';display.textContent='••:••';$('clock-label').textContent=state.me?.hasTapped?'TIME LOCKED':'GO!';$('subdisplay').textContent=state.me?.hasTapped?'WAITING FOR THE OTHERS':'TAP WHEN IT FEELS LIKE 10';stageLabel.textContent=`ROUND ${state.room.round}`;stageTitle.textContent=state.me?.hasTapped?'You’re locked in.':'Feel the time.';stageCopy.textContent=state.me?.hasTapped?'Your exact time will appear here after everyone taps.':'No counting app. No peeking.';tap.hidden=!!state.me?.hasTapped}if(state.room.status!=='results')frame=requestAnimationFrame(tick)};tick()}
startBtn.onclick=newBtn.onclick=async()=>{showError();try{state=await post('/api/timer/start',{code:session.code,hostToken:session.hostToken,playerToken:session.playerToken});offset=state.serverNow-Date.now();render()}catch(error){showError(error.message)}};tap.onclick=async()=>{tap.disabled=true;try{state=await post('/api/timer/tap',{code:session.code,playerToken:session.playerToken});offset=state.serverNow-Date.now();render()}catch(error){showError(error.message)}finally{tap.disabled=false}};$('copy-code').onclick=async()=>{await navigator.clipboard.writeText(session.code);$('copy-code').textContent='COPIED'};$('share').onclick=async()=>{const share={title:'TEN.00 room',text:`Join my hidden-timer room ${session.code}. Closest to 10.00 seconds wins.`,url:roomLink(session.code)};try{if(navigator.share)await navigator.share(share);else{await navigator.clipboard.writeText(`${share.text} ${share.url}`);$('share').textContent='LINK COPIED ✓'}}catch{}};$('leave').onclick=()=>{sessionStorage.removeItem('ten00.session');location.href='/ten-seconds/'};
function escapeHtml(value){const div=document.createElement('div');div.textContent=value;return div.innerHTML}const invite=new URLSearchParams(location.search).get('room');if(invite){document.querySelector('[data-tab="join"]').click();$('join-code').value=invite.toUpperCase().slice(0,5)}session=load();if(session?.code&&session?.playerToken)poll();
